"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { 
  LayoutDashboard, 
  Users, 
  Settings, 
  LogOut,
  CreditCard,
  Shield,
  Activity
} from "lucide-react";

export default function RolesLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const { logout } = useAuth();
  
  // Extract the primary role from the URL to intelligently route the "Dashboard" link
  const currentRole = pathname.split('/')[1] || 'dashboard';

  // Define navigation rules
  const mainNav = [
    { name: "Dashboard", href: `/${currentRole}`, icon: LayoutDashboard },
    { name: "Patient Directory", href: `/shared/patients`, icon: Users },
  ];

  // Role-specific links that only render when the user is in that specific portal
  const roleNav = [
    { name: "Billing & Invoices", href: `/reception/billing`, icon: CreditCard, showIf: currentRole === "reception" },
    { name: "Staff Management", href: `/admin/staff`, icon: Shield, showIf: currentRole === "admin" },
  ];

  const bottomNav = [
    { name: "Settings", href: `/settings`, icon: Settings },
  ];

  return (
    <div className="flex h-screen bg-slate-50">
      {/* Persistent Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col hidden md:flex">
        <div className="h-16 flex items-center px-6 border-b border-slate-200">
          <Activity className="w-6 h-6 text-brand-600 mr-2" />
          <span className="text-lg font-bold text-slate-900 tracking-tight">MediFlow</span>
        </div>

        <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1">
          <div className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 px-3">Main Menu</div>
          
          {mainNav.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link key={item.name} href={item.href} className={`flex items-center px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                isActive ? "bg-brand-50 text-brand-700" : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
              }`}>
                <item.icon className={`w-5 h-5 mr-3 ${isActive ? "text-brand-600" : "text-slate-400"}`} />
                {item.name}
              </Link>
            );
          })}

          {/* Conditional Role Links */}
          {roleNav.filter(item => item.showIf).map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link key={item.name} href={item.href} className={`flex items-center px-3 py-2.5 rounded-lg text-sm font-medium transition-colors mt-1 ${
                isActive ? "bg-brand-50 text-brand-700" : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
              }`}>
                <item.icon className={`w-5 h-5 mr-3 ${isActive ? "text-brand-600" : "text-slate-400"}`} />
                {item.name}
              </Link>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-200 space-y-1">
          {bottomNav.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link key={item.name} href={item.href} className={`flex items-center px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                isActive ? "bg-brand-50 text-brand-700" : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
              }`}>
                <item.icon className={`w-5 h-5 mr-3 ${isActive ? "text-brand-600" : "text-slate-400"}`} />
                {item.name}
              </Link>
            );
          })}
          
          {/* Connected to Auth Context logout handler */}
          <button 
            onClick={logout}
            className="w-full flex items-center px-3 py-2.5 rounded-lg text-sm font-medium text-red-600 hover:bg-red-50 transition-colors text-left"
          >
            <LogOut className="w-5 h-5 mr-3 text-red-500" />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto">
        <div className="p-8">
          {children}
        </div>
      </main>
    </div>
  );
}